import { useNavigate } from "react-router-dom";
import React, { useState, useEffect, useRef } from 'react';
import '../Login/Login.css';
import LoadingButton from '../../components/auth/LoadingButton';
import OTPInput from '../../components/auth/OTPInput';

const API_BASE = import.meta.env.VITE_API_BASE || 'https://crm-backend-4fh2.onrender.com';
export default function VerifyOTP() {
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const [errorMsg, setErrorMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutes
  
  const stageRef = useRef(null);
  const navigate = useNavigate();
  const [nodes, setNodes] = useState([]);

  // ambient floating nodes, generated once on mount
  useEffect(() => {
    const generated = Array.from({ length: 10 }).map((_, i) => ({
      id: i,
      left: Math.random() * 100,
      top: Math.random() * 100,
      delay: Math.random() * 6,
      duration: 7 + Math.random() * 5,
    }));
    setNodes(generated);
  }, []);

  useEffect(() => {
    if (timeLeft <= 0) return;
    const timer = setInterval(() => {
      setTimeLeft(prev => prev - 1);
    }, 1000);
    return () => clearInterval(timer);
  }, [timeLeft]);

  const formatTime = (seconds) => {
    const m = Math.floor(seconds / 60).toString().padStart(2, '0');
    const s = (seconds % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  const handleResend = async () => {
    setErrorMsg('');
    const email = sessionStorage.getItem('resetEmail');
    if (!email) {
      setErrorMsg("Email not found. Please start over.");
      return;
    }
    try {
      const response = await fetch(`${API_BASE}/api/auth/resend-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email })
      });
      const data = await response.json();
      if (!response.ok) {
        setErrorMsg(data.message || "Failed to resend OTP");
      } else {
        setTimeLeft(300);
      }
    } catch (err) {
      setErrorMsg("Network error. Please try again.");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrorMsg("");
    
    const otpValue = otp.join('');
    if (otpValue.length < 6) {
      setErrorMsg("Please enter the 6-digit OTP");
      return;
    }

    const email = sessionStorage.getItem('resetEmail');
    if (!email) {
      setErrorMsg("Session expired. Please restart the process.");
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(`${API_BASE}/api/auth/verify-otp`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, otp: otpValue })
      });
      const data = await response.json();
      if (!response.ok) {
        setErrorMsg(data.message || "Invalid OTP");
      } else {
        navigate("/reset-password");
      }
    } catch (err) {
      setErrorMsg("Network error. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="touchpoint-root">
      <div className="stage" ref={stageRef}>
        <div className="bg-wrap">
          <img className="bg-img" src="data:image/png;base64," alt="" />
          <div className="bg-overlay" />

          <svg className="wire-svg" viewBox="0 0 960 540" preserveAspectRatio="xMidYMid slice">
            <path id="wireTop1" className="pulse-dash" d="M0,120 C160,95 300,150 420,175 C470,185 500,178 500,178" />
            <path id="wireTop2" className="pulse-dash d2" d="M960,95 C820,80 660,150 540,175 C510,182 500,178 500,178" />
            <path id="wireBot1" className="pulse-dash d3" d="M0,260 C150,230 300,270 430,240 C465,232 500,225 500,225" />
            <path id="wireBot2" className="pulse-dash d4" d="M960,230 C800,255 660,265 540,235 C515,229 500,225 500,225" />
          </svg>

          <div className="core-glow" />
        </div>

        {nodes.map((n) => (
          <div
            key={n.id}
            className="node"
            style={{
              left: `${n.left}%`,
              top: `${n.top}%`,
              animationDelay: `${n.delay}s`,
              animationDuration: `${n.duration}s`,
            }}
          />
        ))}

        <div className="eyebrow">Two minds, one thread</div>
        <div className="headline">TOUCHPOINT</div>

      </div>

      <div className="overlay show">
        <div className="panel">
          <h2>Verify OTP</h2>
          <p style={{ fontSize: '0.9rem', color: '#8b9bb4', marginBottom: '20px', textAlign: 'center', lineHeight: '1.4' }}>
            Enter the 6-digit OTP sent to your email.
          </p>

          {errorMsg && (
            <div className="error-message" style={{
              color: '#EF4444',
              marginBottom: '15px',
              fontSize: '0.85rem',
              textAlign: 'center',
              background: 'rgba(239, 68, 68, 0.1)',
              padding: '8px 12px',
              borderRadius: '6px',
              border: '1px solid rgba(239, 68, 68, 0.2)',
              textTransform: 'none',
              letterSpacing: 0
            }}>
              {errorMsg}
            </div>
          )}

          <form onSubmit={handleSubmit}>
            <OTPInput length={6} otp={otp} onOtpChange={setOtp} />
            
            <div style={{ textAlign: 'center', marginBottom: '20px', color: '#8b9bb4', fontSize: '0.9rem' }}>
              {formatTime(timeLeft)}
            </div>

            <LoadingButton
              loading={loading}
              text="Verify OTP"
              loadingText="Verifying..."
            />
          </form>

          <div className="form-footer" style={{ display: 'flex', justifyContent: 'space-between', padding: '0 10px' }}>
            <span
              className="signup-link"
              onClick={timeLeft === 0 ? handleResend : undefined}
              style={{ cursor: timeLeft === 0 ? 'pointer' : 'not-allowed', color: timeLeft === 0 ? '#4fd8ff' : '#8b9bb4' }}
            >
              Resend OTP
            </span>
            <span
              className="signup-link"
              onClick={() => navigate('/login')}
            >
              Back to Login
            </span>
          </div>
        </div>
      </div>
    </div>
  );
}
